import {regionAt,contextAt} from './regional-history.js?v=0.11.1';
// Reading regions, not settlement-density estimates or the territory of an ethnicity.
// A start date means evidence exists in part of the region, never every point.
export const evidenceFrom={iceland:800,hawaii:1000,greenland:-2500,svalbard:1596,antarctica:1820,nz:1250,australia:-65000,'new-guinea':-45000,pacific:-2000,arctic:-20000,'north-america':-14000,mesoamerica:-14000,caribbean:-5000,andes:-14000,amazon:-14000,'southern-america':-14000,nile:-100000,'north-africa':-100000,'west-africa':-100000,'east-africa':-100000,'central-africa':-100000,'southern-africa':-100000,madagascar:500,europe:-100000,'west-asia':-100000,siberia:-40000,steppe:-40000,'south-asia':-100000,'east-asia':-100000,'southeast-asia':-100000};
export function landscapeFeatures(collection,year){return collection.features.filter(f=>year>=evidenceFrom[f.properties.regionId]).map(f=>({...f,properties:{...f.properties,snapshot:year,mode:'context',background:true,basis:'regional',color:'#61c9c0',note:'Географический регион с известными свидетельствами присутствия людей. Подсветка не означает сплошное заселение, точные границы расселения или принадлежность всех жителей одной культуре.'}}));}
export function landscapeContext(feature,year){return contextAt(feature.properties.anchor,year);}
// Stable coarse reading cells. Canvas clips them to modern land; cells have no borders.
export function buildReadingRegions(){const groups=new Map();for(let y=-87;y<87;y+=3){let run=null;for(let x=-180;x<=180;x+=3){const id=x<180?regionAt([x+1.5,y+1.5]).id:null;if(id!==run?.id||(run&&x-run.x>=30)){if(run){const g=groups.get(run.id)||[];g.push([[[run.x,y],[run.x,y+3],[x,y+3],[x,y],[run.x,y]]]);groups.set(run.id,g);}run=id?{id,x}:null;}}}return {type:'FeatureCollection',features:[...groups].map(([regionId,coordinates])=>({type:'Feature',id:'region:'+regionId,properties:{regionId,name:regionId},geometry:{type:'MultiPolygon',coordinates}}))};}
